<?php
$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT b.*,u.name user_name FROM reconciliation_batches b LEFT JOIN users u ON u.id=b.user_id WHERE b.id=?');$q->execute([$id]);$b=$q->fetch();if(!$b){echo '<div class="alert danger">Reconciliation batch not found.</div>';return;}
echo '<div class="page-head"><div><a class="back" href="?page=reconciliation&history=all">← Reconciliation History</a><h1>Reconciliation Batch Details</h1><p>'.e($b['filename']).'</p></div>'.badge('Recorded','info').'</div><div class="batch-banner"><div><span>Batch ID</span><strong>REC-'.$id.'</strong></div><div><span>Date</span><strong>'.e($b['created_at']).'</strong></div><div><span>Processed By</span><strong>'.e($b['user_name']).'</strong></div></div><div class="card table-wrap"><table class="table"><tr><th>Master SKU</th><th>Product</th><th>NetSuite Qty</th><th>Sellable</th><th>Non-Sellable</th><th>Physical</th><th>Variance</th></tr>';$q=$pdo->prepare('SELECT r.*,p.name,p.master_sku FROM reconciliations r JOIN products p ON p.id=r.product_id WHERE r.batch_id=? ORDER BY p.name');$q->execute([$id]);foreach($q as $r)echo '<tr><td>'.e($r['master_sku']).'</td><td>'.e($r['name']).'</td><td>'.(int)$r['netsuite_qty'].'</td><td>'.(int)$r['internal_sellable'].'</td><td>'.(int)$r['nonsellable'].'</td><td>'.(int)$r['physical_total'].'</td><td>'.(int)$r['variance'].'</td></tr>';echo '</table></div><div class="audit-note">This is the recorded snapshot at import time. Reconciliation does not change inventory.</div>';
